// Pure derivation of the LLM-call display view from the engine's ephemeral
// call log records (skill_state.llm_calls). The view vocabulary matches the
// GenAI span channel (ENG-3003 / PR #6264) so the UI carries over unchanged
// when spans replace the record source.
import type { LlmCallRecord } from "../types";

export type LlmCallMessage = {
  role: string;
  content: string;
};

export type LlmCallView = {
  /** Model shown in the row title (response model, falling back to request). */
  model: string;
  /** Side-channel call label ("fact discovery"); null for main chat calls. */
  purpose: string | null;
  isError: boolean;
  errorMessage: string | null;
  durationLabel: string | null;
  tokensLabel: string | null;
  /** Tools the LLM could call for this request. */
  toolNames: string[];
  /** Declared tools withheld from this call by an inactive gate. */
  gatedToolNames: string[];
  /** Tool calls the LLM responded with. */
  responseToolNames: string[];
  promptMessages: LlmCallMessage[];
  responseMessages: LlmCallMessage[];
};

function asMessages(value: unknown): LlmCallMessage[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((entry) => {
    if (typeof entry !== "object" || entry === null) return [];
    const { role, content, tool_calls: toolCalls } = entry as Record<string, unknown>;
    const parts: string[] = [];
    if (typeof content === "string" && content.length > 0) parts.push(content);
    if (Array.isArray(toolCalls) && toolCalls.length > 0) {
      const names = toolCalls
        .map((call) => {
          if (typeof call !== "object" || call === null) return "";
          const name = (call as Record<string, unknown>).name;
          return typeof name === "string" ? name : "";
        })
        .filter(Boolean);
      if (names.length > 0) parts.push(`→ ${names.join(", ")}`);
    }
    if (parts.length === 0) return [];
    return [{ role: typeof role === "string" ? role : "?", content: parts.join("\n") }];
  });
}

function formatDuration(durationMs: number | null): string | null {
  if (durationMs === null) return null;
  if (durationMs >= 1000) return `${(durationMs / 1000).toFixed(1)} s`;
  return `${Math.round(durationMs)} ms`;
}

function formatTokens(record: LlmCallRecord): string | null {
  if (record.input_tokens === null && record.output_tokens === null) return null;
  return `${record.input_tokens ?? "?"} → ${record.output_tokens ?? "?"} tokens`;
}

export function deriveLlmCallView(record: LlmCallRecord): LlmCallView {
  return {
    model: record.response_model ?? record.request_model ?? "LLM",
    purpose: record.purpose,
    isError: record.is_error,
    errorMessage: record.error_message,
    durationLabel: formatDuration(record.latency_ms),
    tokensLabel: formatTokens(record),
    toolNames: record.tool_names,
    gatedToolNames: record.gated_tool_names,
    responseToolNames: record.response_tool_names,
    promptMessages: asMessages(record.prompt_messages),
    responseMessages: asMessages(record.response_messages),
  };
}
